这是根据“可行性与进度”这一页的要求生成的HTML代码，采用计划安排的时间轴式布局，突出8个月周期与三个阶段划分。
```html
<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<style>
:root{
  --bg:#F5F2E9; --surface:#F3F0E7; --ink:#1B2620; --muted:#5C665D;
  --gold:#B4914A; --green:#4F5E43; --blue:#8C9FB2; --line:#A3AC9E;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1920px;height:1080px;overflow:hidden;background:var(--bg)}
body{
  font-family:"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",Arial,sans-serif;
  color:var(--ink);
  -webkit-font-smoothing:antialiased;
}
.slide{position:relative;width:1920px;height:1080px;overflow:hidden;background:var(--bg)}

/* ---------- background field ---------- */
.bg-field{position:absolute;inset:0;z-index:0;background:
  radial-gradient(1100px 780px at 2% 0%,rgba(180,145,74,.10),transparent 70%),
  radial-gradient(880px 760px at 47% 46%,rgba(140,159,178,.10),transparent 70%),
  radial-gradient(950px 760px at 95% 95%,rgba(79,94,67,.10),transparent 72%),
  linear-gradient(168deg,#F8F5EC 0%,#F5F2E9 52%,#EFECE1 100%);}
.bg-field:after{content:"";position:absolute;inset:0;
  background:repeating-linear-gradient(90deg,rgba(27,38,32,.045) 0 1px,transparent 1px 160px);
  opacity:.85;}

.dot-field{position:absolute;z-index:1;opacity:.30;
  background-image:radial-gradient(circle,rgba(27,38,32,.45) 1.05px,transparent 1.15px);
  background-size:15px 15px;}
.dot-a{left:1230px;top:0;width:520px;height:150px}
.dot-b{left:700px;top:940px;width:1000px;height:140px;opacity:.16}

.gridline{position:absolute;top:96px;width:1px;height:900px;background:rgba(27,38,32,.055);z-index:2}
.gl1{left:480px}.gl2{left:960px}.gl3{left:1440px}

/* ---------- frame ---------- */
.top-rule{position:absolute;left:96px;top:48px;width:1728px;height:1px;background:rgba(27,38,32,.34);z-index:6}
.rail-tick{position:absolute;left:96px;width:16px;height:1px;background:rgba(27,38,32,.42);z-index:6}
.rail-tick.t1{top:48px;width:26px;height:2px}

/* ---------- header ---------- */
.meta{position:absolute;left:96px;top:66px;z-index:9;
  font-size:14px;font-weight:600;letter-spacing:4.4px;color:#6b7369}

h1{position:absolute;left:96px;top:106px;z-index:9;
  font-family:"Songti SC","STSong","SimSun",Georgia,"Times New Roman",serif;
  font-size:82px;line-height:1.14;font-weight:600;letter-spacing:2px;
  color:#1B2620;white-space:nowrap}

.gold-rule{position:absolute;left:96px;top:232px;width:104px;height:3px;background:var(--gold);z-index:9}

.subtitle{position:absolute;left:96px;top:264px;width:1180px;z-index:9;
  font-size:21px;line-height:1.62;color:#5C665D;letter-spacing:.6px}

/* ---------- cycle badge ---------- */
.cycle{position:absolute;right:96px;top:96px;width:344px;height:232px;z-index:10;
  background:rgba(243,240,231,.88);
  border:1px solid rgba(27,38,32,.16);
  padding:28px 32px 24px;overflow:hidden}
.cycle:before{content:"";position:absolute;left:0;top:0;width:100%;height:4px;background:var(--gold)}
.cycle:after{content:"";position:absolute;right:-46px;bottom:-46px;width:132px;height:132px;border-radius:50%;
  border:1px solid rgba(27,38,32,.12)}
.cycle .lbl{font-size:13px;letter-spacing:3.6px;font-weight:600;color:#6b7369}
.cycle .num{margin-top:16px;display:flex;align-items:baseline;gap:12px}
.cycle .num b{
  font-family:"Songti SC","STSong","SimSun",Georgia,serif;
  font-size:104px;line-height:.92;font-weight:600;color:#1B2620;letter-spacing:-1px}
.cycle .num i{font-style:normal;font-size:25px;font-weight:600;color:#4a544c;letter-spacing:2px}
.cycle .sub{margin-top:14px;font-size:13.5px;color:#7d877c;letter-spacing:1.4px}

/* ---------- timeline cards ---------- */
.track{position:absolute;left:96px;top:370px;width:1728px;height:320px;z-index:8}
.stage{position:absolute;top:0;height:320px;overflow:hidden;
  background:rgba(243,240,231,.92);
  border:1px solid rgba(27,38,32,.14);
  padding:40px 38px 34px;}
.stage:before{content:"";position:absolute;left:0;top:0;width:100%;height:5px}
.stage.s1{left:10px;width:412px}
.stage.s2{left:442px;width:628px}
.stage.s3{left:1090px;width:628px}
.s1:before{background:var(--gold)}
.s2:before{background:var(--green)}
.s3:before{background:var(--blue)}

.stage .idx{position:absolute;right:36px;top:32px;
  font-size:13px;font-weight:700;letter-spacing:3px;color:#98a096}
.stage .mon{
  font-family:"Songti SC","STSong","SimSun",Georgia,serif;
  font-size:58px;line-height:1.06;font-weight:600;color:#1B2620;letter-spacing:1px;
  margin-top:4px;white-space:nowrap}
.stage .rule{width:56px;height:2px;background:rgba(27,38,32,.22);margin:26px 0 24px}
.stage .ttl{font-size:27px;line-height:1.5;font-weight:600;color:#2b352e;letter-spacing:1.2px}

/* ---------- axis ---------- */
.axis{position:absolute;left:96px;top:750px;width:1728px;height:1px;background:rgba(27,38,32,.32);z-index:7}
.ticks{position:absolute;left:96px;top:740px;width:1728px;height:11px;z-index:7;
  background-image:linear-gradient(to right,rgba(27,38,32,.40) 0 1px,transparent 1px);
  background-size:216px 11px}
.mlab{position:absolute;top:760px;z-index:7;font-size:12px;font-weight:600;letter-spacing:1.6px;color:#8a938a;
  transform:translateX(-50%)}
.m1{left:96px}.m2{left:312px}.m3{left:528px}.m4{left:744px}
.m5{left:960px}.m6{left:1176px}.m7{left:1392px}.m8{left:1608px}

/* ---------- note ---------- */
.note{position:absolute;left:96px;top:836px;width:1728px;height:100px;z-index:9;
  display:flex;align-items:center;gap:28px;
  padding:0 36px;
  background:linear-gradient(90deg,rgba(79,94,67,.10),rgba(79,94,67,.035) 62%,rgba(79,94,67,0));
  border-left:4px solid var(--green);
  border-top:1px solid rgba(27,38,32,.12);
  border-bottom:1px solid rgba(27,38,32,.12)}
